<script setup lang="ts">
import {useWorkModeText} from '../workMode'
const {w}=useWorkModeText()
import {onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {shiftRuleSummary} from '../restPolicy'
import {hours} from '../time'
import {usePhaseThreeText} from '../phaseThreeText'
import type {AttendanceDetail} from '../types'
import {reviewText,issueText} from '../attendanceReview'
import BreakSummaryTable from '../components/BreakSummaryTable.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const id=String(useRoute().params.scheduleId),{api,home,t,p,base,loading,failure,load,format,english}=usePhasePage(),data=ref<AttendanceDetail|null>(null),{q}=usePhaseThreeText()
const r=(key:Parameters<typeof reviewText>[0])=>reviewText(key,english())
function refresh(){void load(()=>api().get<AttendanceDetail>('/attendance/'+id),v=>data.value=v)}
onMounted(refresh)
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{p('attendance')}} · {{p('detail')}}</h2><button :disabled="loading" @click="refresh">{{t('refresh')}}</button></header><PhaseStatus :failure="failure" :loading="loading"/><template v-if="data&&!loading"><p v-if="data.attendance.exempt" role="status">{{w('exempt')}}</p><dl class="wf-details"><dt>{{p('employee')}}</dt><dd>{{data.attendance.schedule.employeeName}} · {{data.attendance.schedule.employeeNo}}</dd><dt>{{p('workDate')}}</dt><dd>{{data.attendance.schedule.workDate}} · {{p(data.attendance.schedule.status)}}</dd><dt>{{p('timezone')}}</dt><dd>{{data.attendance.schedule.timezone}}</dd><dt>{{p('snapshot')}}</dt><dd>{{data.attendance.schedule.shift.name}} · {{shiftRuleSummary(data.attendance.schedule.shift,p(data.attendance.schedule.shift.breakMode),english())}}<template v-if="!data.attendance.schedule.shift.rules&&data.attendance.schedule.shift.breakPaid"> · {{p('breakPaid')}}</template></dd><dt>{{p('plan')}}</dt><dd>{{format(data.attendance.schedule.startAt,data.attendance.schedule.timezone)}} – {{format(data.attendance.schedule.endAt,data.attendance.schedule.timezone)}}</dd><dt>{{p('inAt')}}</dt><dd>{{format(data.attendance.session?.inAt,data.attendance.schedule.timezone)}}</dd><dt>{{p('outAt')}}</dt><dd>{{format(data.attendance.session?.outAt,data.attendance.schedule.timezone)}}</dd><dt>{{p('grossHours')}}</dt><dd>{{hours(data.attendance.grossSeconds)}}</dd><dt>{{p('breakHours')}}</dt><dd>{{hours(data.attendance.breakSeconds)}}</dd><dt>{{p('workHours')}}</dt><dd>{{hours(data.attendance.workSeconds)}}</dd><dt>{{p('breaks')}}</dt><dd><div v-for="(b,i) in data.attendance.session?.breaks||[]" :key="i">{{data.attendance.schedule.shift.rules?.breaks.find(r=>r.id===b.ruleId)?.name||''}} {{format(b.start,data.attendance.schedule.timezone)}} – {{format(b.end,data.attendance.schedule.timezone)}}</div><span v-if="!data.attendance.session?.breaks.length">—</span><div v-if="data.attendance.session?.breakStartedAt">{{format(data.attendance.session.breakStartedAt,data.attendance.schedule.timezone)}} – {{p('OPEN')}}</div></dd><dt>{{p('anomalies')}}</dt><dd><span v-for="a in data.attendance.anomalies" :key="a" class="wf-badge">{{issueText(a,english())!==a?issueText(a,english()):p(a as 'OPEN')}}</span><span v-if="!data.attendance.anomalies.length">—</span></dd></dl><BreakSummaryTable :summaries="data.attendance.breakSummary"/><p class="wf-hint">{{p('factsHint')}}</p><RouterLink v-if="!data.attendance.exempt&&home?.myself?.id===data.attendance.schedule.employeeId&&data.attendance.schedule.status!=='cancelled'&&!data.corrections.some(c=>c.status==='pending')" class="wf-button primary" :to="base+'/corrections/new?schedule='+id">{{p('newCorrection')}}</RouterLink><div class="wf-inline wf-section"><RouterLink v-if="!data.attendance.exempt&&home?.myself?.id===data.attendance.schedule.employeeId&&data.attendance.schedule.status!=='cancelled'" :to="{path:base+'/leaves/new',query:{schedule:id,date:data.attendance.schedule.workDate}}">{{q('newLeave')}}</RouterLink><RouterLink v-if="data.attendance.schedule.status!=='cancelled'" :to="base+'/approvals/'+id">{{q('approvalDetail')}}</RouterLink></div><h2 class="wf-section">{{p('events')}}</h2><div class="wf-table-wrap"><table><thead><tr><th>{{p('actual')}}</th><th>{{p('status')}}</th><th>{{w('actualMode')}}</th><th>{{w('eventName')}}</th></tr></thead><tbody><tr v-for="e in data.events" :key="e.id"><td>{{format(e.occurredAt,data.attendance.schedule.timezone)}}</td><td>{{p(e.action as 'IN')}}</td><td>{{e.clockMode?w(e.clockMode):'—'}}</td><td class="wf-wrap-text">{{e.location?.description||'—'}}</td></tr><tr v-if="!data.events.length"><td colspan="4" class="wf-empty">{{t('empty')}}</td></tr></tbody></table></div><h2 class="wf-section">{{p('history')}}</h2><div v-for="c in data.corrections" :key="c.id" class="wf-history"><RouterLink :to="base+'/corrections/'+c.id+'?schedule='+id">{{format(c.createdAt,data.attendance.schedule.timezone)}} · {{p(c.status)}}</RouterLink><p>{{c.reason}}</p><p v-if="c.reviewNote">{{p('note')}}: {{c.reviewNote}}</p></div><p v-if="!data.corrections.length" class="wf-empty">{{t('empty')}}</p></template></section></template>

